REVOKE ALL ON FUNCTION public.integration_revocation_actors(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.integration_revocation_actors(uuid) TO service_role; ALTER FUNCTION public.integration_revocation_actors(uuid) SECURITY INVOKER; CREATE OR REPLACE FUNCTION public.integration_revocation_actors(_org uuid) RETURNS TABLE(id uuid,display_name text) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT p.id,p.display_name FROM public.profiles p WHERE EXISTS(SELECT 1 FROM public.integration_keys k WHERE k.organization_id=_org AND k.revoked_by=p.id) $$;